import{_ as e,o as t,c as i,aA as l}from"./chunks/framework.BMzE2Z9R.js";const u=JSON.parse('{"title":"网站架构","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"about/web_arch.md","filePath":"about/web_arch.md","lastUpdated":1778399398000}'),o={name:"about/web_arch.md"};function r(n,a,c,s,h,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="网站架构" tabindex="-1">网站架构 <a class="header-anchor" href="#网站架构" aria-label="Permalink to &quot;网站架构&quot;">​</a></h1><h2 id="_1-需求分析" tabindex="-1">1. 需求分析 <a class="header-anchor" href="#_1-需求分析" aria-label="Permalink to &quot;1. 需求分析&quot;">​</a></h2><h3 id="_1-1-目前痛点" tabindex="-1">1.1. 目前痛点 <a class="header-anchor" href="#_1-1-目前痛点" aria-label="Permalink to &quot;1.1. 目前痛点&quot;">​</a></h3><ol><li>协会网站更新难、维护难</li><li>新手入门难、理论理解难</li><li>想学NARS无从下手</li><li>不知道我们这群人在干什么</li></ol><p>针对以上问题，我提出了对下一代网站的需求</p><h3 id="_1-2-对网站的需求" tabindex="-1">1.2. 对网站的需求 <a class="header-anchor" href="#_1-2-对网站的需求" aria-label="Permalink to &quot;1.2. 对网站的需求&quot;">​</a></h3><ol><li>美观、简介的前端界面</li><li>将散落在各处的NARS相关资源整合起来</li><li>降低新手了解NARS的门槛</li><li>降低编程人员进行NARS实现的难度</li></ol><h2 id="_2-编程实现" tabindex="-1">2. 编程实现 <a class="header-anchor" href="#_2-编程实现" aria-label="Permalink to &quot;2. 编程实现&quot;">​</a></h2><ol><li>中国境内站点Gitee：<a href="https://gitee.com/Hailay/agi-society-cn" target="_blank" rel="noreferrer">agi-society-cn: 中国通用人工智能协会网站 (gitee.com)</a></li><li>境外编辑GitHub：<a href="https://github.com/Hailaylin/agi-society-cn" target="_blank" rel="noreferrer">Hailaylin/agi-society-cn: save and edit china agi society wiki web content (github.com)</a></li></ol><p>两个站点互为镜像备份，修改一个会自动同步到另一个。</p><p>网站静态内容部署在中国深圳阿里云服务器中，以满足合规要求。</p><p>同时本地使用python脚本系统构建静态网页内容。</p><h2 id="_3-改进" tabindex="-1">3. 改进 <a class="header-anchor" href="#_3-改进" aria-label="Permalink to &quot;3. 改进&quot;">​</a></h2><div class="callout" data-callout="note"><div class="callout-title"><div class="callout-title-icon"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-pencil"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"></path><path d="m15 5 4 4"></path></svg></div><div class="callout-title-inner">想法1</div></div><div class="callout-content"><p></p><p>可选用具有知识网络结构<a href="https://quartz.jzhao.xyz/" target="_blank" rel="noreferrer">Quartz 4</a>，适合将Obsidian的双向链接知识库发布在网上。</p></div></div>',14)])])}const p=e(o,[["render",r]]);export{u as __pageData,p as default};
